/* VARIANT G · CUT — page 5906 */
[class*="section-"] {
  --cut-bone: #F5F0E6;
  --cut-ink: #151515;
  --cut-rust: #A34B3C;
  --cut-amber: #D89A2B;
  --cut-display: "Bodoni Moda", Didot, "Times New Roman", serif;
  --cut-sans: "Jost", "Helvetica Neue", Arial, sans-serif;
  background: var(--cut-bone);
  color: var(--cut-ink);
  overflow: hidden;
}
[class*="section-"] *,
[class*="section-"] *::before,
[class*="section-"] *::after {
  box-sizing: border-box;
  border-radius: 0 !important;
  box-shadow: none !important;
}
[class*="section-"] :is(p,a,button,input,textarea,label,span) {
  font-family: var(--cut-sans) !important;
}
[class*="section-"] :is(h1,h2,h3,h4,.text-h2,.title) {
  font-family: var(--cut-display) !important;
  font-weight: 400 !important;
}

/* HERO · poster block */
[class*="section-hero-g---poster-block-"] {
  background: var(--cut-ink) !important;
}
[class*="section-hero-g---poster-block-"] :is(.q-card,.q-card__section,[data-test-id="generic-carousel"]) {
  margin: 0 !important;
  padding: 0 !important;
  max-width: none !important;
  background: var(--cut-ink) !important;
}
[class*="section-hero-g---poster-block-"] .swiper,
