[class*="section-hero-g---poster-block-"] .swiper-slide,
[class*="section-hero-g---poster-block-"] [class*="carousel-item-"] {
  height: 520px !important;
  min-height: 520px !important;
}
[class*="section-hero-g---poster-block-"] .row.justify-center.position-relative,
[class*="section-hero-g---poster-block-"] [class*="carousel-item-"] > .position-relative {
  height: 520px !important;
  min-height: 520px !important;
  background: var(--cut-ink) !important;
  overflow: hidden !important;
}
[class*="section-hero-g---poster-block-"] img.full-width,
[class*="section-hero-g---poster-block-"] [class*="carousel-item-"] img {
  width: 100% !important;
  height: 520px !important;
  object-fit: cover !important;
  object-position: center !important;
  clip-path: polygon(43% 0,100% 0,100% 100%,31% 100%);
}
[class*="section-hero-g---poster-block-"] .flex.absolute-bottom {
  position: absolute !important;
  inset: 0 !important;
  display: flex !important;
  align-items: center !important;
  width: 100% !important;
  padding: 48px !important;
  background: transparent !important;
  pointer-events: none;
}
[class*="section-hero-g---poster-block-"] .flex.absolute-bottom .container {
  width: 100% !important;
  max-width: none !important;
  padding: 0 !important;
}
[class*="section-hero-g---poster-block-"] .col.message {
  width: min(48%,640px) !important;
  max-width: 640px !important;
  padding: 0 !important;
  text-align: left !important;
  pointer-events: auto;
}
[class*="section-hero-g---poster-block-"] .title {
  display: block;
  margin: 0 0 18px !important;
  font-size: clamp(72px,9vw,128px) !important;
  line-height: .78 !important;
  letter-spacing: -.055em !important;
